  endfunction

  // --------------------------------------------------------------------------
  // layer 1/3: eth -- 14 bytes of fields
  // --------------------------------------------------------------------------
  logic [LEN_W-1:0]  off_eth;
  logic [LEN_W-1:0]  len_eth;
  logic [111:0] win_eth;

  assign off_eth = LEN_W'(0);

  assign win_eth = i_win[0 +: 112];

  logic [47:0]         eth_dst_mac           ;  // bits 0..47, 48b bytes
  logic [47:0]         eth_src_mac           ;  // bits 48..95, 48b bytes
  logic [15:0]         eth_ethertype         ;  // bits 96..111, 16b enum ethertype_e, big-endian

  assign eth_dst_mac            = {win_eth[7:0], win_eth[15:8], win_eth[23:16], win_eth[31:24], win_eth[39:32], win_eth[47:40]};
  assign eth_src_mac            = {win_eth[55:48], win_eth[63:56], win_eth[71:64], win_eth[79:72], win_eth[87:80], win_eth[95:88]};
  assign eth_ethertype          = {win_eth[103:96], win_eth[111:104]};

