  assign win_ipv4 = i_win[112 +: 160];

  logic [3:0]          ipv4_version          ;  // bits 0..3, 4b uint
  logic [3:0]          ipv4_ihl              ;  // bits 4..7, 4b uint
  logic [5:0]          ipv4_dscp             ;  // bits 8..13, 6b uint
  logic [1:0]          ipv4_ecn              ;  // bits 14..15, 2b uint
  logic [15:0]         ipv4_total_length     ;  // bits 16..31, 16b uint, big-endian
  logic [15:0]         ipv4_identification   ;  // bits 32..47, 16b uint, big-endian
  logic [2:0]          ipv4_flags            ;  // bits 48..50, 3b uint
  logic [12:0]         ipv4_frag_offset      ;  // bits 51..63, 13b uint, big-endian
  logic [7:0]          ipv4_ttl              ;  // bits 64..71, 8b uint
  logic [7:0]          ipv4_protocol         ;  // bits 72..79, 8b enum ip_proto_e
  logic [15:0]         ipv4_hdr_checksum     ;  // bits 80..95, 16b uint, big-endian
