  assign ipv4_ihl               = win_ipv4[3:0];
  assign ipv4_dscp              = win_ipv4[15:10];
  assign ipv4_ecn               = win_ipv4[9:8];
  assign ipv4_total_length      = {win_ipv4[23:16], win_ipv4[31:24]};
  assign ipv4_identification    = {win_ipv4[39:32], win_ipv4[47:40]};
  assign ipv4_flags             = win_ipv4[55:53];
  assign ipv4_frag_offset       = {win_ipv4[52:48], win_ipv4[63:56]};
  assign ipv4_ttl               = win_ipv4[71:64];
  assign ipv4_protocol          = win_ipv4[79:72];
  assign ipv4_hdr_checksum      = {win_ipv4[87:80], win_ipv4[95:88]};
  assign ipv4_src_ip            = {win_ipv4[103:96], win_ipv4[111:104], win_ipv4[119:112], win_ipv4[127:120]};
  assign ipv4_dst_ip            = {win_ipv4[135:128], win_ipv4[143:136], win_ipv4[151:144], win_ipv4[159:152]};

