  // downstream part-select off the end of the window; len_bad_ipv4 is what
  // the error path reads, and it looks at the unclamped value.
  logic [LEN_W-1:0] len_raw_ipv4;
  logic             len_bad_ipv4;
  assign len_raw_ipv4 = LEN_W'(ipv4_ihl) * LEN_W'(4);
  assign len_bad_ipv4 = (len_raw_ipv4 < LEN_W'(20)) ||
                        (len_raw_ipv4 > LEN_W'(60));
  assign len_ipv4     = len_bad_ipv4 ? LEN_W'(20) : len_raw_ipv4;

  // --------------------------------------------------------------------------
  // layer 3/3: udp -- 8 bytes of fields
  // --------------------------------------------------------------------------
  logic [LEN_W-1:0]  off_udp;
  logic [LEN_W-1:0]  len_udp;
  logic [63:0] win_udp;

  assign off_udp = off_ipv4 + len_ipv4;

  // The offset is only known at run time, so one shift places the window; every
  // field below is then a static slice of it.
  logic [9:0] sh_udp;
  assign sh_udp  = 10'({off_udp, 3'b000});
  assign win_udp = i_win[sh_udp +: 64];

  logic [15:0]         udp_src_port          ;  // bits 0..15, 16b uint, big-endian
  logic [15:0]         udp_dst_port          ;  // bits 16..31, 16b uint, big-endian
  logic [15:0]         udp_length            ;  // bits 32..47, 16b uint, big-endian
  logic [15:0]         udp_checksum          ;  // bits 48..63, 16b uint, big-endian

  assign udp_src_port           = {win_udp[7:0], win_udp[15:8]};
  assign udp_dst_port           = {win_udp[23:16], win_udp[31:24]};
  assign udp_length             = {win_udp[39:32], win_udp[47:40]};
  assign udp_checksum           = {win_udp[55:48], win_udp[63:56]};

  assign len_udp = LEN_W'(8);

  // --------------------------------------------------------------------------
  // Chain walk
  // --------------------------------------------------------------------------
  logic active_eth;
  logic trunc_fix_eth;
  logic ok_eth;
  logic settled_eth;
  logic active_ipv4;
  logic trunc_fix_ipv4;
  logic trunc_len_ipv4;
