    end else if (active_ipv4 && len_bad_ipv4) begin
      err = 3'(WS_BAD_HDR_LEN);
    end else if (active_ipv4 && trunc_len_ipv4) begin
      err = 3'(WS_TRUNCATED);
    end else if (active_udp && trunc_fix_udp) begin
