        o_layer_valid <= layers_ok;
        o_err         <= err;
        o_hdr_bytes   <= o_strip_bytes;

        o_eth_dst_mac            <= eth_dst_mac;
        o_eth_src_mac            <= eth_src_mac;
        o_eth_ethertype          <= eth_ethertype;

        o_ipv4_version           <= ipv4_version;
        o_ipv4_ihl               <= ipv4_ihl;
        o_ipv4_dscp              <= ipv4_dscp;
        o_ipv4_ecn               <= ipv4_ecn;
        o_ipv4_total_length      <= ipv4_total_length;
        o_ipv4_identification    <= ipv4_identification;
        o_ipv4_flags             <= ipv4_flags;
        o_ipv4_frag_offset       <= ipv4_frag_offset;
        o_ipv4_ttl               <= ipv4_ttl;
        o_ipv4_protocol          <= ipv4_protocol;
        o_ipv4_hdr_checksum      <= ipv4_hdr_checksum;
        o_ipv4_src_ip            <= ipv4_src_ip;
        o_ipv4_dst_ip            <= ipv4_dst_ip;

        o_udp_src_port           <= udp_src_port;
        o_udp_dst_port           <= udp_dst_port;
        o_udp_length             <= udp_length;
        o_udp_checksum           <= udp_checksum;
      end
    end
  end

